//! 🏛️ Explicit typed Architect fields mapped to their authored relational columns.
use crate::kernel::*;
use crate::registers::*;
use store::sqlite_snapshot::{SqliteDatabase,SqliteRow,SqliteValue,SqliteSnapshotControl,SqliteSnapshotPhase,artifact::{Cell,Projection}};
use std::collections::{BTreeMap,BTreeSet};
pub const SCHEMA:&str=include_str!("🗄️.sql");
fn admit_schema(control:&SqliteSnapshotControl<'_>)->Result<(),String>{if SCHEMA.len()>control.limits().max_schema_bytes{Err("Architect authored SQLite schema exceeds schema byte limit".into())}else{Ok(())}}
enum FieldCell<'a>{Borrowed(Cell<'a>),Decimal(String)}
trait SqlField:Sized{
 const WIDTH:usize;
 fn append<'a>(&'a self,cells:&mut Vec<FieldCell<'a>>);
 fn read(row:&SqliteRow,index:&mut usize,native:&mut dsl::NativeDecodeControl<'_>)->Result<Self,String>;
}
fn next<'a>(row:&'a SqliteRow,index:&mut usize)->Result<&'a SqliteValue,String>{let value=row.values.get(*index).ok_or("Architect scalar column is absent")?;*index+=1;Ok(value)}
fn cells<'a>(values:&'a[FieldCell<'a>])->Vec<Cell<'a>>{values.iter().map(|v|match v{FieldCell::Borrowed(c)=>*c,FieldCell::Decimal(text)=>Cell::Text(text)}).collect()}
impl SqlField for String{
const WIDTH:usize=1;
 fn append<'a>(&'a self,c:&mut Vec<FieldCell<'a>>){c.push(FieldCell::Borrowed(Cell::Text(self)))}
 fn read(r:&SqliteRow,i:&mut usize,n:&mut dsl::NativeDecodeControl<'_>)->Result<Self,String>{match next(r,i)?{SqliteValue::Text(text)=>n.copy_text(text),_=>Err("Architect requires a literal text scalar".into())}}
}
impl SqlField for EntityId{
 const WIDTH:usize=1;
 fn append<'a>(&'a self,c:&mut Vec<FieldCell<'a>>){self.0.append(c)}
 fn read(r:&SqliteRow,i:&mut usize,n:&mut dsl::NativeDecodeControl<'_>)->Result<Self,String>{String::read(r,i,n).map(Self)}
}
impl SqlField for bool{
 const WIDTH:usize=1;
 fn append<'a>(&'a self,c:&mut Vec<FieldCell<'a>>){c.push(FieldCell::Borrowed(Cell::Integer(i64::from(*self))))}
 fn read(r:&SqliteRow,i:&mut usize,_:&mut dsl::NativeDecodeControl<'_>)->Result<Self,String>{match next(r,i)?{SqliteValue::Integer(0)=>Ok(false),SqliteValue::Integer(1)=>Ok(true),_=>Err("Architect requires a canonical Boolean".into())}}
}
impl SqlField for u32{
 const WIDTH:usize=1;
 fn append<'a>(&'a self,c:&mut Vec<FieldCell<'a>>){c.push(FieldCell::Borrowed(Cell::Integer(i64::from(*self))))}
 fn read(r:&SqliteRow,i:&mut usize,_:&mut dsl::NativeDecodeControl<'_>)->Result<Self,String>{match next(r,i)?{SqliteValue::Integer(value)=>u32::try_from(*value).map_err(|e|e.to_string()),_=>Err("Architect requires an unsigned32 INTEGER".into())}}
}
impl SqlField for u64{
 const WIDTH:usize=2;
 fn append<'a>(&'a self,c:&mut Vec<FieldCell<'a>>){c.push(FieldCell::Decimal(self.to_string()));c.push(FieldCell::Borrowed(Cell::Integer(*self as i64)))}
 fn read(r:&SqliteRow,i:&mut usize,_:&mut dsl::NativeDecodeControl<'_>)->Result<Self,String>{let decimal=match next(r,i)?{SqliteValue::Text(v)=>v,_=>return Err("Architect requires an exact unsigned64 decimal".into())};let word=match next(r,i)?{SqliteValue::Integer(v)=>*v as u64,_=>return Err("Architect unsigned64 word is absent".into())};if decimal!=&word.to_string(){return Err("Architect unsigned64 query scalar differs from its exact word".into())}Ok(word)}
}
fn float_class(value:f64)->&'static str{if value.is_nan(){"nan"}else if value==f64::INFINITY{"positiveInfinity"}else if value==f64::NEG_INFINITY{"negativeInfinity"}else{"finite"}}
impl SqlField for f64{
 const WIDTH:usize=3;
 fn append<'a>(&'a self,c:&mut Vec<FieldCell<'a>>){c.push(FieldCell::Borrowed(if self.is_nan(){Cell::Null}else{Cell::Real(*self)}));c.push(FieldCell::Borrowed(Cell::Integer(self.to_bits()as i64)));c.push(FieldCell::Borrowed(Cell::Text(float_class(*self))))}
 fn read(r:&SqliteRow,i:&mut usize,_:&mut dsl::NativeDecodeControl<'_>)->Result<Self,String>{let query=next(r,i)?;let value=match next(r,i)?{SqliteValue::Integer(word)=>f64::from_bits(*word as u64),_=>return Err("Architect binary64 exact word is absent".into())};if next(r,i)?!=&SqliteValue::Text(float_class(value).into()){return Err("Architect binary64 class differs".into())}let same=match query{SqliteValue::Null=>value.is_nan(),SqliteValue::Real(v)=>!value.is_nan()&&*v==value,SqliteValue::Integer(v)=>value.is_finite()&&value>=-9223372036854775808.0&&value<9223372036854775808.0&&value.fract()==0.0&&value as i64==*v&&(*v as f64)==value,_=>false};if !same{return Err("Architect binary64 query scalar differs".into())}Ok(value)}
}
macro_rules! nullable{($($t:ty),+)=>{$(impl SqlField for Option<$t>{
 const WIDTH:usize=<$t as SqlField>::WIDTH;
 fn append<'a>(&'a self,c:&mut Vec<FieldCell<'a>>){match self{Some(v)=>v.append(c),None=>c.extend((0..Self::WIDTH).map(|_|FieldCell::Borrowed(Cell::Null)))}}
 fn read(r:&SqliteRow,i:&mut usize,n:&mut dsl::NativeDecodeControl<'_>)->Result<Self,String>{let end=i.checked_add(Self::WIDTH).ok_or("Architect optional width overflow")?;let span=r.values.get(*i..end).ok_or("Architect optional scalar is absent")?;if span.iter().all(|v|matches!(v,SqliteValue::Null)){*i=end;Ok(None)}else{<$t>::read(r,i,n).map(Some)}}
 })+}}
nullable!(String,EntityId,bool,u32,u64,f64);
impl SqlField for TextField{
 const WIDTH:usize=2;
 fn append<'a>(&'a self,c:&mut Vec<FieldCell<'a>>){self.text.append(c);self.format.append(c)}
 fn read(r:&SqliteRow,i:&mut usize,n:&mut dsl::NativeDecodeControl<'_>)->Result<Self,String>{Ok(Self{text:String::read(r,i,n)?,format:Option::<String>::read(r,i,n)?})}
}
impl SqlField for Option<TextField>{
 const WIDTH:usize=3;
 fn append<'a>(&'a self,c:&mut Vec<FieldCell<'a>>){c.push(FieldCell::Borrowed(Cell::Integer(i64::from(self.is_some()))));match self{Some(v)=>v.append(c),None=>{c.push(FieldCell::Borrowed(Cell::Null));c.push(FieldCell::Borrowed(Cell::Null));}}}
 fn read(r:&SqliteRow,i:&mut usize,n:&mut dsl::NativeDecodeControl<'_>)->Result<Self,String>{if bool::read(r,i,n)?{TextField::read(r,i,n).map(Some)}else{if !matches!(next(r,i)?,SqliteValue::Null)||!matches!(next(r,i)?,SqliteValue::Null){return Err("Architect absent text has a payload".into())}Ok(None)}}
}
impl SqlField for TaggedNote{
 const WIDTH:usize=2;
 fn append<'a>(&'a self,c:&mut Vec<FieldCell<'a>>){self.tag.append(c);self.text.append(c)}
 fn read(r:&SqliteRow,i:&mut usize,n:&mut dsl::NativeDecodeControl<'_>)->Result<Self,String>{Ok(Self{tag:String::read(r,i,n)?,text:String::read(r,i,n)?})}
}
macro_rules! enum_sql{($t:ty;$($variant:ident=>$name:literal),+)=>{impl SqlField for $t{
 const WIDTH:usize=1;
 fn append<'a>(&'a self,c:&mut Vec<FieldCell<'a>>){c.push(FieldCell::Borrowed(Cell::Text(match self{$(Self::$variant=>$name),+})))}
 fn read(r:&SqliteRow,i:&mut usize,_:&mut dsl::NativeDecodeControl<'_>)->Result<Self,String>{match next(r,i)?{SqliteValue::Text(v)=>match v.as_str(){$($name=>Ok(Self::$variant)),+,_=>Err("Architect enum symbol is undeclared".into())},_=>Err("Architect enum requires a literal symbol".into())}}
 }}}
