fn emit(p:&mut Projection<'_,'_>,table:&str,key:Option<i64>,values:&[FieldCell<'_>])->Result<i64,String>{let borrowed=cells(values);if let Some(key)=key{p.insert_key(table,key,&borrowed)?;Ok(key)}else{p.insert(table,&borrowed)}}
fn ordered<T:SqlField>(p:&mut Projection<'_,'_>,table:&str,parent:i64,values:&[T])->Result<(),String>{for(ordinal,value)in values.iter().enumerate(){let mut c=Vec::with_capacity(T::WIDTH+2);c.push(FieldCell::Borrowed(Cell::Integer(parent)));c.push(FieldCell::Borrowed(Cell::Integer(i64::try_from(ordinal).map_err(|e|e.to_string())?)));value.append(&mut c);emit(p,table,None,&c)?;}Ok(())}
fn timestamp<'a>(v:&'a TimestampMeta,c:&mut Vec<FieldCell<'a>>){v.created.append(c);v.updated.append(c);v.created_by.append(c);v.updated_by.append(c)}
macro_rules! fields{($cells:ident;$v:ident;$($field:ident $(.$inner:ident)*),+)=>{$($v.$field$(.$inner)*.append(&mut $cells);)+}}
macro_rules! edges{($p:ident,$parent:expr;$v:ident;$($field:ident=>$table:literal),+)=>{$(ordered($p,$table,$parent,&$v.$field)?;)+}}
impl SqlField for TraceLink{
 const WIDTH:usize=5;
 fn append<'a>(&'a self,c:&mut Vec<FieldCell<'a>>){self.id.append(c);self.from_id.append(c);self.to_id.append(c);self.kind.append(c);self.label.append(c)}
 fn read(row:&SqliteRow,index:&mut usize,n:&mut dsl::NativeDecodeControl<'_>)->Result<Self,String>{Ok(Self{id:SqlField::read(row,index,n)?,from_id:SqlField::read(row,index,n)?,to_id:SqlField::read(row,index,n)?,kind:SqlField::read(row,index,n)?,label:SqlField::read(row,index,n)?})}
}
fn meta(p:&mut Projection<'_,'_>,v:&ProgramMeta)->Result<(),String>{let mut c=vec![FieldCell::Borrowed(Cell::Integer(1))];fields!(c;v;schema,document_id,title,subtitle,purpose,industry_sector,project_type,locale,revision,source_system,export_profile);timestamp(&v.timestamps,&mut c);emit(p,"architect_meta",Some(1),&c)?;edges!(p,1;v;terminology=>"architect_meta_term",classification=>"architect_meta_classification",author_ids=>"architect_meta_author");Ok(())}
fn project_definition(p:&mut Projection<'_,'_>,v:&ProjectDefinition)->Result<(),String>{let mut c=vec![FieldCell::Borrowed(Cell::Integer(1))];fields!(c;v;id,code,client_name,owner_organization,brief_summary,problem_statement,vision,mission,geographic_context,development_context,operational_context,funding_model,ownership.owner_id,ownership.authority_id);timestamp(&v.timestamps,&mut c);emit(p,"architect_project",Some(1),&c)?;edges!(p,1;v;objectives=>"architect_project_objective",success_criteria=>"architect_project_success_criterion",project_priorities=>"architect_project_priority",completion_criteria=>"architect_project_completion_criterion",decision_criteria=>"architect_project_decision_criterion",scope_inclusions=>"architect_project_scope_inclusion",scope_exclusions=>"architect_project_scope_exclusion",assumptions=>"architect_project_assumption",constraints_summary=>"architect_project_constraint",dependencies=>"architect_project_dependency",deliverables=>"architect_project_deliverable",phases=>"architect_project_phase",regulatory_context=>"architect_project_regulatory_context");ordered(p,"architect_project_consultant",1,&v.ownership.consultant_ids)?;ordered(p,"architect_project_participant",1,&v.ownership.participant_ids)?;Ok(())}
fn governance(p:&mut Projection<'_,'_>,v:&Governance)->Result<(),String>{let mut c=vec![FieldCell::Borrowed(Cell::Integer(1))];fields!(c;v;id,framework,quality_policy,risk_appetite,audit_schedule,owner_id,review_cycle,policy_ownership_id,requirement_ownership_id,risk_ownership_id,reporting_frequency);emit(p,"architect_governance",Some(1),&c)?;edges!(p,1;v;roles=>"architect_governance_role",responsibilities=>"architect_governance_responsibility",approval_matrix=>"architect_governance_approval",escalation_paths=>"architect_governance_escalation",meeting_cadence=>"architect_governance_meeting_cadence",decision_rights=>"architect_governance_decision_right",change_control_process=>"architect_governance_change_control",compliance_obligations=>"architect_governance_compliance_obligation",document_control=>"architect_governance_document_control",stakeholder_engagement_plan=>"architect_governance_stakeholder_engagement",ethics_policy=>"architect_governance_ethics_policy",data_governance=>"architect_governance_data_governance",review_hierarchy=>"architect_governance_review_hierarchy",accountability_rules=>"architect_governance_accountability",exception_management=>"architect_governance_exception",governance_performance=>"architect_governance_performance");Ok(())}
fn child<S>(p:&mut Projection<'_,'_>,slot:&str,v:&store::ArtifactChild<S>)->Result<(),String>{let target=&v.target;p.insert("architect_child",&[Cell::Integer(1),Cell::Text(slot),Cell::Text(&v.child_id),Cell::Text(&target.artifact_id),Cell::Text(&target.dialect.artifact_kind),Cell::Text(&target.dialect.standard),Cell::Text(&target.dialect.subset)])?;Ok(())}
fn project_core(snapshot:&super::ProgramSnapshot,p:&mut Projection<'_,'_>)->Result<(),String>{p.insert_key("architect_document",1,&[Cell::Text(&snapshot.schema)])?;meta(p,&snapshot.meta)?;project_definition(p,&snapshot.project)?;governance(p,&snapshot.governance)?;child(p,"knowledge",&snapshot.knowledge)?;child(p,"benchmarks",&snapshot.benchmarks)?;ordered(p,"architect_trace",1,&snapshot.traces)}
fn read_timestamp(row:&SqliteRow,index:&mut usize,n:&mut dsl::NativeDecodeControl<'_>)->Result<TimestampMeta,String>{Ok(TimestampMeta{created:SqlField::read(row,index,n)?,updated:SqlField::read(row,index,n)?,created_by:SqlField::read(row,index,n)?,updated_by:SqlField::read(row,index,n)?})}
trait RegisterSql:Sized{
 const REGISTER:&'static str;
 fn admit_native(values:&[dsl::FieldValue],native:&mut dsl::NativeDecodeControl<'_>,count:&mut usize,maximum:usize)->Result<(),String>;
 fn rows(&self)->Result<usize,String>;
 fn project(&self,p:&mut Projection<'_,'_>,ordinal:usize)->Result<(),String>;
 fn restore(r:&mut Reader<'_,'_,'_>,row:&SqliteRow)->Result<Self,String>;
}
fn quantity(p:&mut Projection<'_,'_>,entity:i64,slot:&str,table:&str,v:&QuantitySpec)->Result<(),String>{let mut c=vec![FieldCell::Borrowed(Cell::Integer(entity)),FieldCell::Borrowed(Cell::Text(slot))];fields!(c;v;unit,min,max,target,current,forecast,peak,average);let id=emit(p,"architect_quantity_spec",None,&c)?;p.insert_key(table,entity,&[Cell::Integer(id)])}
fn read_quantity(r:&mut Reader<'_,'_,'_>,entity:i64,slot:&str,table:&'static str)->Result<QuantitySpec,String>{let link=r.body(table,entity,2)?;let row=r.body("architect_quantity_spec",link.integer(1)?,25)?;if row.integer(1)?!=entity||row.text(2)?!=slot{return Err("Architect quantity belongs to a different entity or slot".into())}let mut i=3;let n=&mut*r.native;Ok(QuantitySpec{unit:SqlField::read(row,&mut i,n)?,min:SqlField::read(row,&mut i,n)?,max:SqlField::read(row,&mut i,n)?,target:SqlField::read(row,&mut i,n)?,current:SqlField::read(row,&mut i,n)?,forecast:SqlField::read(row,&mut i,n)?,peak:SqlField::read(row,&mut i,n)?,average:SqlField::read(row,&mut i,n)?})}
macro_rules! register_sql{
 ($type:ty,$register:literal,$table:literal;[$($scalar:ident:$scalar_type:ty),*];[$($list:ident:$list_type:ty=>$edge:literal),*];[$($quantity:ident=>$quantity_edge:literal),*])=>{
 impl RegisterSql for $type{
  const REGISTER:&'static str=$register;
  fn admit_native(values:&[dsl::FieldValue],native:&mut dsl::NativeDecodeControl<'_>,count:&mut usize,maximum:usize)->Result<(),String>{if values.is_empty(){return Ok(())}let spec=Self::__dsl_spec_controlled(native)?;let header_spec=EntityHeader::__dsl_spec_controlled(native)?;let ownership_spec=Ownership::__dsl_spec_controlled(native)?;native.scoped_stage(|native|{native.begin_stage(values.len())?;for value in values{native.step()?;let row=native_record(value)?;admit_header(row,&spec,&header_spec,&ownership_spec,native,count,maximum)?;$(add_rows(count,native_list(native_field(row,&spec,stringify!($list))?)?.len(),maximum)?;)*$(let _=stringify!($quantity);add_rows(count,2,maximum)?;)*}native.checkpoint()})}
  fn rows(&self)->Result<usize,String>{let h=&self.header;let mut count=2usize;for n in[h.tags.len(),h.notes.len(),h.ownership.consultant_ids.len(),h.ownership.participant_ids.len(),$(self.$list.len(),)*] {count=count.checked_add(n).ok_or("Architect register row count overflow")?;}$(let _=&self.$quantity;count=count.checked_add(2).ok_or("Architect quantity row count overflow")?;)*Ok(count)}
  fn project(&self,p:&mut Projection<'_,'_>,ordinal:usize)->Result<(),String>{let id=header(p,$register,ordinal,&self.header)?;let mut c=Vec::with_capacity(0$(+<$scalar_type as SqlField>::WIDTH)*);$(self.$scalar.append(&mut c);)*emit(p,$table,Some(id),&c)?;$(ordered(p,$edge,id,&self.$list)?;)*$(quantity(p,id,stringify!($quantity),$quantity_edge,&self.$quantity)?;)*Ok(())}
  fn restore(r:&mut Reader<'_,'_,'_>,header_row:&SqliteRow)->Result<Self,String>{let header=r.header(header_row)?;let row=r.body($table,header_row.rowid,1$(+<$scalar_type as SqlField>::WIDTH)*)?;let mut index=1;$(let $scalar=<$scalar_type as SqlField>::read(row,&mut index,r.native)?;)*$(let $list=r.list::<$list_type>($edge,header_row.rowid)?;)*$(let $quantity=read_quantity(r,header_row.rowid,stringify!($quantity),$quantity_edge)?;)*Ok(Self{header,$($scalar,)*$($list,)*$($quantity,)*})}
 }
 }}
fn register_project<T:RegisterSql>(p:&mut Projection<'_,'_>,values:&[T])->Result<(),String>{for(index,value)in values.iter().enumerate(){value.project(p,index)?;}Ok(())}
fn add_rows(count:&mut usize,size:usize,maximum:usize)->Result<(),String>{*count=count.checked_add(size).filter(|count|*count<=maximum).ok_or("Architect semantic rows exceed caller limit")?;Ok(())}
macro_rules! snapshot_registers{($($field:ident:$type:ty),+)=>{
 fn forecast(s:&super::ProgramSnapshot,c:&mut SqliteSnapshotControl<'_>,phase:SqliteSnapshotPhase)->Result<usize,String>{c.checkpoint(phase,0,0)?;let mut count=6usize;let maximum=c.limits().max_rows;add_rows(&mut count,0,maximum)?;for size in[s.meta.terminology.len(),s.meta.classification.len(),s.meta.author_ids.len(),s.project.objectives.len(),s.project.success_criteria.len(),s.project.project_priorities.len(),s.project.completion_criteria.len(),s.project.decision_criteria.len(),s.project.scope_inclusions.len(),s.project.scope_exclusions.len(),s.project.assumptions.len(),s.project.constraints_summary.len(),s.project.dependencies.len(),s.project.deliverables.len(),s.project.phases.len(),s.project.regulatory_context.len(),s.project.ownership.consultant_ids.len(),s.project.ownership.participant_ids.len(),s.governance.roles.len(),s.governance.responsibilities.len(),s.governance.approval_matrix.len(),s.governance.escalation_paths.len(),s.governance.meeting_cadence.len(),s.governance.decision_rights.len(),s.governance.change_control_process.len(),s.governance.compliance_obligations.len(),s.governance.document_control.len(),s.governance.stakeholder_engagement_plan.len(),s.governance.ethics_policy.len(),s.governance.data_governance.len(),s.governance.review_hierarchy.len(),s.governance.accountability_rules.len(),s.governance.exception_management.len(),s.governance.governance_performance.len(),s.traces.len()]{add_rows(&mut count,size,maximum)?;}let mut visits=0usize;$(for row in &s.$field{add_rows(&mut count,row.rows()?,maximum)?;visits=visits.checked_add(1).ok_or("Architect forecast work count overflow")?;if visits%256==0{c.checkpoint(phase,visits,0)?;}})+c.checkpoint(phase,visits,count)?;Ok(count)}
 fn project(s:&super::ProgramSnapshot,c:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,String>{let total=forecast(s,c,SqliteSnapshotPhase::ProjectSnapshot)?;let mut p=Projection::new(SCHEMA,c)?;project_core(s,&mut p)?;$(register_project(&mut p,&s.$field)?;)+p.checkpoint_total(total)?;p.finish()}
 fn restore(database:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->Result<super::ProgramSnapshot,String>{c.check_database(database,SqliteSnapshotPhase::ReconstructSnapshot)?;store::sqlite_snapshot::validate_sqlite_database_schema(database,SCHEMA,c.limits()).map_err(|e|e.to_string())?;let maximum=c.limits().max_value_bytes;let mut progress=|event:semio_framework_value::native_decoding::NativeDecodeProgress|c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,event.completed,event.total).is_ok();let mut n=dsl::NativeDecodeControl::new(maximum,&mut progress);n.charge(std::mem::size_of::<super::ProgramSnapshot>())?;let mut r=Reader{database,native:&mut n,groups:BTreeMap::new(),bodies:BTreeMap::new(),headers:None,used:BTreeSet::new()};let root=r.singleton("architect_document",2)?;let schema=r.native.copy_text(root.text(1)?)?;let s=super::ProgramSnapshot{schema,meta:read_meta(&mut r)?,project:read_project(&mut r)?,governance:read_governance(&mut r)?,knowledge:read_child(&mut r,"knowledge")?,benchmarks:read_child(&mut r,"benchmarks")?,traces:r.list("architect_trace",1)?,$($field:register_restore::<$type>(&mut r)?,)+};r.finish()?;Ok(s)}
 fn admit_native(record:&dsl::RecordValue,n:&mut dsl::NativeDecodeControl<'_>,maximum:usize)->Result<(),String>{let mut count=6usize;add_rows(&mut count,0,maximum)?;let spec=super::ProgramSnapshot::__dsl_spec_controlled(n)?;admit_core(record,&spec,n,&mut count,maximum)?;$(<$type>::admit_native(native_list(native_field(record,&spec,stringify!($field))?)?,n,&mut count,maximum)?;)+n.checkpoint()}
}}
fn native_record(value:&dsl::FieldValue)->Result<&dsl::RecordValue,String>{match value{dsl::FieldValue::Record(row)=>Ok(row),dsl::FieldValue::Block(value)=>native_record(value),_=>Err("Architect native record shape differs".into())}}
